    '& code': { background: 'transparent', padding: 0, fontSize: 12 },
  },
  reasoningText: { whiteSpace: 'pre-wrap', borderLeft: '2px solid #e0e0e0', paddingLeft: 8, marginTop: 4, maxHeight: 180, overflowY: 'auto' },
